<?php

namespace App\Gfx;

/** Build-time-free procedural wall posters, shared by native OpenGL and WASM/WebGL. */
final class PosterFactory
{
    public const ATLAS_COLS = 4;
    public const ATLAS_ROWS = 4;
    public const TILE_W = 200;
    public const TILE_H = 290;

    /**
     * 4x4 atlas. Four cells keep the banal "VOTRE PUB ICI" gag; the other
     * twelve are generated by the DeepSeek MinitelRosePoster supplied for the game.
     */
    public static function advert(): \GdImage
    {
        $atlas = imagecreatetruecolor(self::ATLAS_COLS * self::TILE_W, self::ATLAS_ROWS * self::TILE_H);
        imagealphablending($atlas, true);
        imagesavealpha($atlas, true);
        imagefill($atlas, 0, 0, imagecolorallocate($atlas, 16, 8, 24));

        $rose = new MinitelRosePoster();
        for ($i = 0; $i < self::ATLAS_COLS * self::ATLAS_ROWS; $i++) {
            $tile = ($i % 4 === 0)
                ? self::advertTile($i)
                : $rose->generate(361500 + $i * 97);
            $x = ($i % self::ATLAS_COLS) * self::TILE_W;
            $y = intdiv($i, self::ATLAS_COLS) * self::TILE_H;
            imagecopyresized(
                $atlas,
                $tile,
                $x,
                $y,
                0,
                0,
                self::TILE_W,
                self::TILE_H,
                imagesx($tile),
                imagesy($tile),
            );
            imagedestroy($tile);
        }
        return $atlas;
    }

    private static function advertTile(int $variant): \GdImage
    {
        $im = imagecreatetruecolor(MinitelRosePoster::WIDTH, MinitelRosePoster::HEIGHT);
        imagealphablending($im, true);
        imagesavealpha($im, true);

        $ink = imagecolorallocate($im, 18, 10, 28);
        $paper = imagecolorallocate($im, 245, 214 - ($variant % 3) * 12, 70 + ($variant % 2) * 18);
        $pink = imagecolorallocate($im, 242, 52, 151);
        $cyan = imagecolorallocate($im, 55, 226, 226);
        $white = imagecolorallocate($im, 250, 245, 224);

        imagefilledrectangle($im, 0, 0, 399, 579, $paper);
        imagefilledrectangle($im, 16, 16, 383, 563, $ink);
        imagefilledrectangle($im, 28, 32, 371, 142, $pink);
        imagefilledrectangle($im, 28, 158, 371, 494, $white);
        imagefilledrectangle($im, 28, 512, 371, 532, $cyan);

        imagestring($im, 5, 150, 76, 'VOTRE', $white);
        imagestring($im, 5, 170, 250, 'PUB', $ink);
        imagestring($im, 5, 170, 320, 'ICI', $pink);
        imagestring($im, 5, 116, 432, '3615 / RESERVE', $ink);
        imagestring($im, 3, 126, 468, 'EMPLACEMENT DISPONIBLE', $ink);

        imagefilledrectangle($im, 40, 174, 68, 202, $cyan);
        imagefilledrectangle($im, 332, 438, 360, 466, $cyan);
        imagerectangle($im, 6, 6, 393, 573, $pink);
        return $im;
    }
}
